INSERT INTO public.pilar_angulos (id, pilar_id, red, es_capa, slug, nombre, descripcion, orden, minimo) SELECT '34d9e648-65bb-4ae8-b7af-24122a09ed0c', (SELECT id FROM public.categorias WHERE slug = 'bienestar-e-impacto'), 'linkedin', false, 'como-se-mide', 'Cómo se mide', 'Medir el impacto humano y no solo la adopción: indicadores, evaluación de pilotos, instrumentos. Voz declarativa, carrusel PDF con datos.', 2, NULL WHERE NOT EXISTS (SELECT 1 FROM public.pilar_angulos WHERE pilar_id = (SELECT id FROM public.categorias WHERE slug = 'bienestar-e-impacto') AND slug = 'como-se-mide');
INSERT INTO public.pilar_angulos (id, pilar_id, red, es_capa, slug, nombre, descripcion, orden, minimo) SELECT '20821dab-f942-4ea4-ae62-75e4b7099c4b', (SELECT id FROM public.categorias WHERE slug = 'bienestar-e-impacto'), 'linkedin', false, 'lo-que-se-ve', 'Lo que se ve', 'Lo que RRHH y yo observamos en las personas y los equipos cuando ya usan IA, incluso como apoyo emocional: estrés, desgaste, bienestar. Voz íntima, texto en primera persona.', 1, NULL WHERE NOT EXISTS (SELECT 1 FROM public.pilar_angulos WHERE pilar_id = (SELECT id FROM public.categorias WHERE slug = 'bienestar-e-impacto') AND slug = 'lo-que-se-ve');
INSERT INTO public.pilar_angulos (id, pilar_id, red, es_capa, slug, nombre, descripcion, orden, minimo) SELECT '0b466605-0b68-47cd-b4c8-7e25f8409595', (SELECT id FROM public.categorias WHERE slug = 'psicologia-en-la-mesa'), 'linkedin', false, 'lo-que-construyo', 'Lo que construyo', 'Mi caso a la vista. Una psicóloga que construye y entrena modelos: Eureka Engine, Game Over Impostora, videojuegos, el diplomado, Conidolly, mi etapa de psicóloga cyborg. Voz íntima, fotos reales, demos y video.', 2, 0.33333333333333333333 WHERE NOT EXISTS (SELECT 1 FROM public.pilar_angulos WHERE pilar_id = (SELECT id FROM public.categorias WHERE slug = 'psicologia-en-la-mesa') AND slug = 'lo-que-construyo');
INSERT INTO public.pilar_angulos (id, pilar_id, red, es_capa, slug, nombre, descripcion, orden, minimo) SELECT '198b89fd-37e1-4669-9385-f73c7209142a', (SELECT id FROM public.categorias WHERE slug = 'psicologia-en-la-mesa'), 'linkedin', false, 'lo-que-planteo', 'Lo que planteo', 'La IA y la salud mental como tema país y académico: IA ética, datos de salud, regulación y el rol de la psicología en diseñar y evaluar la IA. Voz declarativa, carrusel con datos y fuentes revisadas.', 1, NULL WHERE NOT EXISTS (SELECT 1 FROM public.pilar_angulos WHERE pilar_id = (SELECT id FROM public.categorias WHERE slug = 'psicologia-en-la-mesa') AND slug = 'lo-que-planteo');
INSERT INTO public.pilar_angulos (id, pilar_id, red, es_capa, slug, nombre, descripcion, orden, minimo) SELECT '006928d9-7804-4b6a-b250-29a43032971c', (SELECT id FROM public.categorias WHERE slug = 'mi-nueva-partida'), 'instagram', false, 'pruebalo-tu', 'Pruébalo tú', 'Usar la IA con criterio en su propia reinvención. Reel de pantalla y carrusel paso a paso. Series «Prompt con inteligencia emocional» y «Pequeño experimento».', 2, 0.33333333333333333333 WHERE NOT EXISTS (SELECT 1 FROM public.pilar_angulos WHERE pilar_id = (SELECT id FROM public.categorias WHERE slug = 'mi-nueva-partida') AND slug = 'pruebalo-tu');
